import pathlib,hashlib,json
base=pathlib.Path(__file__).resolve().parent; root=base.parents[1]
groups={
'scripts/verify_artifacts.py':[(1,14,'توثيق واستيرادات المسار وNumPy وpandas ودوال الإعداد واللقطات والتقارير وتحميل النماذج والتخزين؛ MODELS تشمل أربعة نماذج وPersistence.'),(17,24,'verify_asset تحمل اللقطة المحققة والنوافذ والتنبؤات وتتحقق من أسماء النماذج ومقاييسها وتختار الإغلاق المعدل لليومي والإغلاق للشهري.'),(25,30,'لكل نموذج تفحص تطابق تواريخ الأهداف مع الاختبار وترتيب الأصل قبل الهدف ومطابقة القيم الحالية واللاحقة مع اللقطة؛ لا يثبت ذلك تواريخ إتاحة البيانات المنقحة.'),(31,39,'تعيد تحميل أربعة نماذج على CPU وتقارن تنبؤاتها بالمحفوظ ضمن tolerances وتفحص تفسيراتها، ثم تتحقق من تاريخ آخر هدف لتقييس LSTM وتعيد ملخص الأصل.'),(42,50,'verify_explanation تقرأ جودة التفسير وتؤكد عدم تغير التنبؤ وأن الخلفية في التدريب، وتعيد بناء تنبؤ SHAP من base ومجموع القيم، وتتحقق من أن كل فهرس اختبار.'),(51,56,'تقرأ LIME لنفس الفهرس وتتحقق من تواريخ الهدف والأصل وصيغة الخطأ المطلق، ثم من أحجام الرسوم؛ لا تختبر أن خطأ LIME صغير أو أن التفسير سببي.'),(59,71,'main تحدد تشغيل full وتتحقق من بصمة الرسالة ومنشأ النتائج والمرجع التاريخي وبصمات الفهرس، ثم تدقق كل أصل وتكتب verification.json وتطبع. لم يُنفذ هنا؛ كتابته تغير ملف أثر.'),(74,75,'حارس التشغيل المباشر.')],
'scripts/verify_cpu_replay.py':[(1,15,'توثيق واستيرادات قياسية وتعريف الجذر وMPLCONFIGDIR ومساري src وscripts على sys.path؛ قد ينشئ matplotlib cache عند الاستيراد.'),(18,27,'main تقرأ مسار إيصال افتراضي وتحتفظ بـ socket.connect ثم تعرف غلافاً يرفض الاتصال الخارجي ذي عنوان tuple.'),(29,40,'تستبدل connect وتستورد NumPy وTorch والحزمة وأدوات التحقق والتفسير والتحميل والبذور. هذا الحجب يقتصر على المسار المستبدل ولا يثبت منع كل أشكال الشبكة.'),(42,53,'تؤكد نسخة torch CPU وغياب CUDA وتضبط البذرة والخيوط، وتستورد وحدات الحزمة وتسجلها، ثم تتحقق من بصمات تشغيل full.'),(54,65,'تحت حد الخيوط تفحص كل أصل ثم تحمل نوافذ ونماذج AAPL على CPU، وتختار أربع خلفيات تدريبية وعينة اختبار واحدة لفحص توافق محدود.'),(66,74,'لكل نموذج تحسب تنبؤاً وتفسير SHAP وLIME جديداً بميزانية صغيرة، وتتحقق من جمع SHAP وثبات التنبؤ ونهائية R² وتحفظ نتائج probe في الذاكرة؛ هذا حساب تفسير جديد لا تدريب ولا بديل عن الآثار الأصلية.'),(75,86,'تجد 15 مهمة تحقق وتعيد تشغيل تنبؤاتها ومقاييسها، ثم تكتب إيصالاً في الوجهة؛ الافتراضي تحت artifacts/deployment، لذلك الوصف read-only يتعلق بالأدلة الأصلية لا بغياب أي كتابة.'),(89,90,'حارس التشغيل؛ لم ينفذ في جلسة التوثيق.')],
'scripts/verify_scientific_validation.py':[(1,15,'توثيق واستيرادات argparse وreplace والوقت والمسارات وNumPy وpandas ووظائف المشروع للتحميل والتنبؤ والتقييم والهاش.'),(18,28,'replay_job تحمل التصميم والنوافذ وتستبدل التقسيمات من NPZ دون pickle، وتفحص الهدف المحول وتقرأ الجدول وتحمل نماذج CPU وتحسب توقعات النماذج والمراجع.'),(29,39,'لكل نموذج تتحقق من تواريخ الهدف والأصل والقيم الفعلية، وتقارن الهدف المتوقع: LSTM بسماح مطلق يساوي ثمانية أضعاف epsilon لـ float32 مضروباً في مقياس هدف التدريب، والآخرون بسماح 1e-9. التسامح يعالج فروق الأجهزة لا يضمن تماثل كل البيئات.'),(40,46,'تحول التوقع المحفوظ إلى dtype التنبؤ الأصلي قبل إعادة تركيب السعر لتكرار دقة الحساب، وتحسب أقصى اختلاف وتتحقق من بصمات completion وتعيد ملخص المهمة.'),(49,63,'verify_aggregate تقرأ التنبؤات والمقاييس المجمعة، وترشح لكل مجموعة وتمنع تكرار تاريخ الهدف ثم تعيد حساب evaluation_metrics وتقارن جميع النتائج، وتعيد عدد الصفوف. bootstrap ضمن evaluation_metrics يعاد حسابه عند التشغيل.'),(66,74,'preservation_receipt تقارن حجم وبصمة الملفات مع سجل ما قبل التحقق وتفرض عدم تغيرها، وتعيد العدد وبصمتي السجل وZIP؛ تعتمد على شمول السجل وصحته.'),(77,89,'main تقرأ الوجهة وتضبط البذرة وتحدد الأصل وتؤكد وجود 15 مهمة، ثم تعيد تشغيلها وتدقق التجميع والمحافظة وتكتب verification.json وتطبع. ليست قراءة خالصة لأن الإيصال يكتب؛ لم يُنفذ هنا.'),(92,93,'حارس التنفيذ المباشر.')]
}
manifest={}
for path,entries in groups.items():
 raw=(root/path).read_bytes(); src=raw.decode('utf8').splitlines(); digest=hashlib.sha256(raw).hexdigest(); name=path.replace('/','_')+'.md'; out=['# شرح `'+path+'`','',f'بصمة المصدر SHA-256: `{digest}`.','','لم تُنفذ إعادة التشغيل أو تدقيق النتائج في هذه الجلسة.','']
 for a,b,d in entries: out += [f'## الأسطر {a}–{b}','','```python',*src[a-1:b],'```','',d,'']
 (base/'line_by_line'/name).write_text('\n'.join(out),encoding='utf8'); manifest[path]={'document':'line_by_line/'+name,'ranges':[[a,b] for a,b,_ in entries],'sha256':digest,'review':'يدوية غير مستقلة','quote_verification':'آلي'}
(base/'verification_scripts_manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf8')
